var e=(n,o)=>({text:n,ms:o}),h=[{id:"intro",label:"Hello, and the share",priority:1,needs:"call",entry:"clean",lines:[e("Thanks for joining. I know a CV that opens a call is a bit much.",3600),e("So let me be quick about why I'm in your applicant pool.",3e3),e("Click around while I talk. You could even complete all 17 achievements.",4200),e("Let me get my screen up.",2400)],beats:[{at:3,cue:"share"}],commentary:[e("Starting from the top, then.",2e3)],brief:[e("I'm Nam. Let me get my screen up.",2400)]},{id:"cv",label:"The CV",priority:2,needs:"cv",entry:"clean",lines:[e("This is the CV.",1800),e("Seven years leading the front end of an online Mahjong client.",4e3),e("Four players, four networks, one shared board, no excuses about latency.",4600),e("Desktop, then web, then a Unity renderer embedded in a React app.",4400),e("Working cross-team with basically everyone: design, server, QA, and the people who get the call when a table breaks at midnight.",5600),e("Before that, four years of optimisation research. Two papers and a book chapter.",4800),e("And before that, C++ on signing hardware. Correctness was the product.",4400),e("Here are my tech skills. Claude made this whole section redundant, LOL.",4200),e("Education: Vietnam, Japan, Sweden. I love tonkotsu.",3600)],beats:[{at:0,roll:{of:"cv",to:0,ms:500}},{at:1,roll:{of:"cv",to:"Experience",ms:1400}},{at:5,roll:{of:"cv",to:.42,ms:1600}},{at:6,roll:{of:"cv",to:.55,ms:1400}},{at:7,roll:{of:"cv",to:"Skills",ms:1500}},{at:8,roll:{of:"cv",to:"Education",ms:1400}}],bail:{at:1,rewind:!0,lines:[e("Pap pap pap. Seven years of my life, and it gets three seconds of yours?",3600),e("Come back here.",1600),e("\u2026Just kidding. Carry on.",2200)]},commentary:[e("The CV, yes. One data module renders this and the call, so they cannot disagree.",4200)],brief:[e("The CV. Seven years on a real-time client, and the research before it.",3200)],triggers:['[data-icon="cv"]','.cb-tab[data-tab-id="cv"]']},{id:"jobreq",label:"Against the job requirement",priority:3,needs:"share",entry:"clean",lines:[e("Great. So how does all that score against the job requirement?",3600),e("I've got you covered.",1800),e("Degree, check. Five years of software development, check.",4e3),e("Front end, testing, launches, architecture. Check, check, check, check.",4400),e("You get a check. And you get a check. And everybody gets a check.",4200),e("Yeah. I'm a safe hire.",2600)],beats:[{at:1,cue:"tab:jobad"},{at:2,roll:{of:"page",to:.25,ms:1500}},{at:3,roll:{of:"page",to:.6,ms:1800}},{at:4,roll:{of:"page",to:1,ms:1800}}],commentary:[e("The posting, line by line. Every requirement has something here you can click on.",4200)],brief:[e("Every requirement in the posting, with the evidence next to it.",3200)],triggers:['.cb-tab[data-tab-id="jobad"]']},{id:"built",label:"How this was built",priority:4,needs:"share",entry:"clean",lines:[e("Now let me show you how this was built.",2800),e("No framework. No runtime dependency. One stylesheet and a reducer.",4400),e("The interface was measured off the real product, not eyeballed. The measurements are in there, including the one that was wrong.",5600),e("There is a size budget that fails the build.",3e3),e("And the tests are real. They run in your browser, and you can break them.",4600),e("One person and an agent, one week. The retractions are in the commit log with everything else.",4800)],beats:[{at:0,cue:"tab:built"},{at:2,roll:{of:"page",to:.35,ms:1600}},{at:3,roll:{of:"page",to:.6,ms:1400}},{at:4,roll:{of:"page",to:.8,ms:1400}},{at:5,roll:{of:"page",to:1,ms:1400}}],commentary:[e("The build: no dependencies, measured rather than eyeballed, budget enforced in CI.",4400)],brief:[e("No framework, no dependencies, measured off the real product.",3e3)],triggers:['.cb-tab[data-tab-id="built"]']},{id:"offclock",label:"Off the clock",priority:5,entry:"clean",lines:[e("Last but not least, let me get you some more achievements.",3400),e("These are hidden in the calendar on the home screen. You found some of them.",4200),e("Here are the ones you didn't.",2400),e("Bottom line: I'm pretty fun at work. And if I'm not, throw me out of a plane. I love that.",5200),e("Sorry if that came across corny. I would be in Hollywood otherwise.",4e3)],beats:[{at:2,cue:"eggs"}],commentary:[e("Stand-up, short films, and a zombie walk that made the local news.",3800)],brief:[e("Stand-up, acting, a zombie walk on SVT. All in the calendar.",2800)],triggers:['[data-tab="offclock"]']},{id:"close",label:"The close",priority:6,entry:"clean",lines:[e("And that's everything I came here to show you. The rest is yours.",3800),e("Everything on screen is real and nothing here breaks. Open the panels, drag the windows, run the tests.",5e3),e("The plain document is top left if you'd rather just read it, and there's a PDF next to it.",4600),e("Thank you for your time. Genuinely.",3e3)],beats:[{at:3,cue:"park"}],commentary:[e("The plain document is top left, and there is a PDF beside it.",3600)],brief:[e("That's me. Plain document top left, PDF beside it. Thanks for the time.",3400)]}],p=[{q:"Why are you applying for this, and why now?",lines:[e("Since you're still here, the part a CV never answers.",3400),e("I've spent seven years making one product better for the same players. I know that job very well now.",5e3),e("I want the version of it where the constraints are harder and the people around me are better than me.",4800)]},{q:"What do you actually like about this kind of work?",lines:[e("What I like is the moment a thing on screen behaves exactly the way you predicted it would.",4600),e("Front end is the only discipline where you find out immediately whether you were right.",4400)]},{q:"What are you strongest at?",lines:[e("Strength: I am unreasonable about measuring things. This whole page is built off getBoundingClientRect rather than screenshots.",5600),e("And I finish. Two platform migrations on a live product with real money on the tables. Nobody got to stop halfway.",5200)]},{q:"What are your weaknesses, honestly?",lines:[e("Weakness, honestly: I go too deep too early. I built a WebGL effects pipeline for this site and then deleted it, because it needed a camera permission I decided we should never ask for.",6400),e("That was the right call and it cost me two days. I'd rather tell you that than pretend the two days were planned.",5e3),e("The other one: I am funnier in writing than in a first meeting. You may have noticed.",4200)]},{q:"How do you work with other people?",lines:[e("On a live client you are never the only owner of anything. Server, design, QA, support: everything I shipped went through all four.",5400),e("I write the thing down before I argue about it. Most disagreements turn out to be two people describing different problems.",5200)]},{q:"What happens when you are wrong?",lines:[e("I record it. There is a measurement in this build that produced a contradiction: the reaction band could not be in two places at once.",5400),e("I wrote up the failure instead of quietly re-running it, and the write-up is what found the real rule.",4800)]},{q:"What is the hardest thing you have shipped?",lines:[e("Hardest: shared state across four seats, with reconnection, on latency you do not control.",4600),e("One of those four players is always on hotel wifi. That constraint shaped more of my career than any framework has.",5e3)]},{q:"Why should we take the risk?",lines:[e("Last one. Why take the risk: because you can check every claim on this page by clicking on it.",4800),e("That's the whole pitch. Thanks for listening to it.",3200)]}],d=/^[a-z]+:[a-z]+$/,t=(n,o,r,i,l)=>({id:n,group:o,kind:d.test(r)?"event":"click",on:r,text:i,ms:l}),m=[t("desk-first","desktop","desk:first","A real desktop: windows, explorer, browser, player.",2800),t("desk-drag","desktop","desk:drag","Yeah, you can do that.",1800),t("desk-snap","desktop","desk:snap","Snap layouts. I call this one Chrominion.",2600),t("desk-min","desktop","desk:min","It's not gone. It's on the taskbar, being patient.",2800),t("desk-close","desktop","desk:close","Fine. That one wasn't important.",2200),t("desk-folder","desktop","desk:folder","Real folders. Well, real-ish.",2200),t("desk-resize","desktop","desk:resize","It resizes properly too. Container queries, not media queries.",3200),t("desk-clock","desktop",".dk-clock","That clock is the only honest thing on this desktop.",3e3),t("desk-tray","desktop",".dk-tray-btn:not(.dk-clock)","Sorry, no wifi. That's a picture of wifi.",2800),t("desk-start","desktop",".dk-start","There is a Start menu. There is even a shutdown, and it shuts something down.",3600),t("desk-tv","desktop",".dk-tv-btn","Task view. Alt-Tab belongs to your real computer, not to mine.",3400),t("desk-peek","desktop",".dk-peek-card","Those previews are the windows themselves, scaled. They cannot go stale.",3600),t("cb-tab","browser",".cb-tab","Tabs open, tabs close. A browser inside a browser.",2800),t("cb-new","browser",".cb-new","Go on then. Open a new one.",2200),t("cb-omni","browser",".cb-omni-in","You can type a real URL in there. It will actually go.",3e3),t("cb-riichi","browser",'.cb-tab[data-tab-id="riichi"]',"That tab is the live client. Not a screenshot of it. The actual client.",3400),t("cb-work","browser",'.cb-tab[data-tab-id="work"]',"Everything I have built that I am allowed to show you.",3e3),t("p-a11y","panel",'[data-tab="a11y"]',"Accessibility, audited live. That panel runs the audit against this page while you watch.",4400),t("p-tests","panel",'[data-tab="tests"]',"Same suite the CI runs. There's a switch that breaks them on purpose, if you want to see red.",4400),t("p-perf","panel",'[data-tab="perf"]',"Real numbers, off this page, not a benchmark I chose.",3e3),t("p-net","panel",'[data-tab="net"]',"Push that to Hotel wifi. That is the setting I actually design for.",3400),t("p-spec","panel",'[data-tab="spec"]',"Every measurement, including the one that turned out to be wrong.",3400),t("p-people","panel","panel:people","That's who's in the call. It is a short list.",2600),t("p-chat","panel","panel:chat","The messages are scripted. Nobody is typing.",2600),t("p-host","panel","panel:host","Host controls. You can take the document away with you.",3e3),t("p-about","panel","panel:about","The career, as a timeline. Overlapping roles get their own lane, honestly.",3800),t("c-hand","call",'[data-ctl="hand"]',"\u2026Sorry about that. That is the one control that lies to you.",3600),t("c-react","call",'[data-ctl="react"]',"Those reactions are mine, not Google\u2019s.",2600),t("c-cam","call",'[data-ctl="camera"]',"It never asks for your camera. It just changes the icon.",3200),t("c-mic","call",'[data-ctl="mic"]',"The mic check is real, by the way. Timed off the live product.",3200)],a=(n,o,r,i)=>({id:n,tier:o,text:r,ms:i}),b=[a("s1","settled","Take your time. It's all there.",2400),a("s2","settled","You're actually reading it. That's rarer than you'd think.",3400),a("s3","settled","Good. That section is the one I would have picked too.",3200),a("b1","browsing","Wow, you're a fast reader.",2200),a("b2","browsing","Right, you have the gist.",2e3),a("b3","browsing","Skimming. Respectable.",2e3),a("b4","browsing","Ah, you know what you are looking for.",2600),a("b5","browsing","Fine, I'll keep up.",2e3),a("k1","skimming","CV? Yeah, yeah. You want more, I see.",3e3),a("k2","skimming","Okay, you're hunting for something specific. Keep going, it is in here.",4e3),a("k3","skimming","I'll talk faster.",1800),a("k4","skimming","You are moving faster than I can talk. Which is a compliment, I think.",3800),a("k5","skimming","Every one of these has something behind it, for the record.",3400),a("x1","bolting","Pap pap pap. Seven years of my life, and it gets three seconds of yours?",3800),a("x2","bolting","Alright. You win. You drive.",2400),a("x3","bolting","I am going to stop narrating and let you get on with it.",3200),a("x4","bolting","You've clearly done this before. I'll shut up.",3e3)],y={shorten:e("Lots to look at. I will keep these short.",2800),handOver:e("You clearly know your way around. I will get out of the way. Everything is where you would expect, and the plain document is in the top left. Thanks for the time.",6e3),stopped:e("Of course. I will leave you to it.",2400),resume:e("Still here? I will carry on then.",2600)},g=12e4,s=(n,o,r)=>({text:n,ms:o,gap:r}),f=[s("Still here?",2600,4e3),s("The call does not actually end, by the way. Sit as long as you like.",4200,7e3),s("Questions? My email is on the way out. Or the referral note, if you know somebody. \u{1F64F}",5e3,1e4),s("There is nothing more to see here. I swear.",3400,14e3),s("\u2026okay. There are two easter eggs. That is all I am saying.",4e3,18e3),s("You are unusually patient. That is a promising sign for a code review.",4400,22e3),s("Alright. Genuinely, thank you for your time. Good luck with the rest of the pile. \u{1F44B}",5200,0)];function u(){let n=[],o=0;for(let r of[...h].sort((i,l)=>i.priority-l.priority))r.lines.forEach((i,l)=>{n.push({at:Math.round(o/1e3),part:r,index:l,line:i,beats:(r.beats??[]).filter(c=>c.at===l)}),o+=i.ms});return n}function w(){return h.reduce((n,o)=>n+o.lines.reduce((r,i)=>r+i.ms,0),0)}function k(n){return u().map(o=>({at:o.at,speaker:n,text:o.line.text}))}export{h as a,p as b,m as c,b as d,y as e,g as f,f as g,u as h,w as i,k as j};
